/*
 * A103286  Triangle, read by rows, where row n+1 is formed by sorting, in
 *          ascending order, the result of the convolution of row n with
 *          {2,1}.
 * https://oeis.org/A103286
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   sequence generated by constructing a triangle whose rows are the
 *            sorted convolution of the previous row with {2,1}. No
 *            closed‑form formula is known; the terms are produced by a direct
 *            construction algorithm
 * Range:     u8 n <= 27, u16 n <= 56, u32 n <= 56, u64 n <= 56, u128 n <= 56,
 *            big any n
 * Validated: partial, pass, 57 terms through n = 56 (2026-11-03)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stddef.h>
#include <stdint.h>
#include "../utils/mem.h"

static int cmp_seq_t(const void *a, const void *b)
{
    seq_t va = *(const seq_t *)a;
    seq_t vb = *(const seq_t *)b;
    if (va < vb) return -1;
    if (va > vb) return 1;
    return 0;
}

seq_t a(idx_t n)
{
    /* Memoised storage of all terms built so far. */
    static seq_t *seq   = NULL;   /* flattened sequence of all terms      */
    static idx_t  seq_len = 0;    /* current number of terms stored       */
    static idx_t  seq_cap = 0;    /* capacity of seq[]                    */

    /* Storage for the current row before convolution. */
    static seq_t *row   = NULL;   /* array of the current row values      */
    static idx_t  row_len = 0;    /* length of the current row            */

    /* Initialisation on the first call. */
    if (seq_len == 0) {
        seq_cap = 64;
        seq = mem_new(seq_t, seq_cap);
        row_len = 1;
        row = mem_new(seq_t, 1);
        seq[0] = row[0] = (seq_t)1;
        seq_len = 1;
    }

    /* Generate rows until we have enough terms for index n. */
    while (seq_len <= n) {
        /* Compute the next row (convolution with {2,1}) */
        idx_t next_len = row_len + 1;
        seq_t *next = mem_new(seq_t, (size_t)next_len);

        next[0] = row[0] * 2;
        for (idx_t i = 1; i < row_len; ++i)
            next[i] = row[i-1] + row[i] * 2;
        next[row_len] = row[row_len-1];

        /* Sort the convolution result to form the next row. */
        mem_qsort(next, (size_t)next_len, sizeof(seq_t), cmp_seq_t);

        /* Resize the main sequence array if required. */
        if (seq_len + next_len > seq_cap) {
            seq_cap = seq_cap ? seq_cap * 2 : 64;
            while (seq_len + next_len > seq_cap)
                seq_cap *= 2;
            seq = mem_resize(seq_t, seq, seq_cap);
        }

        /* Append the sorted row to the flattened sequence. */
        for (idx_t i = 0; i < next_len; ++i)
            seq[seq_len++] = next[i];

        /* Advance to the next row. */
        mem_free(row);
        row = next;
        row_len = next_len;
    }

    return seq[n];
}
